{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "keep",
  "supportive_card_ids": ["C16", "C13", "C05", "C08", "C09", "C12", "C07", "C60"],
  "contradictory_card_ids": ["C50", "C51", "C52", "C56", "C58", "C63", "C66"],
  "prediction_basis_card_ids": ["C16", "C13", "C05", "C08", "C09", "C12", "C07", "C60"],
  "claims": [
    {
      "claim": "Direct human absolute/relative bioavailability records for nucleoside analogs in the gold contexts are at or above the 20% threshold: zalcitabine absolute F ≈80% (range 54–127%) in fasted patients and 70–90% in broader studies; didanosine fasted F was 22–29%; zidovudine F was 0.61 in patients with cirrhosis.",
      "card_ids": ["C16", "C13", "C05", "C08", "C09", "C12", "C07"]
    },
    {
      "claim": "L5 gut-wall/intestinal-metabolism records do not provide an AICAR-specific F or presystemic-loss outcome; the nucleoside-related records show measurable rat intestinal permeability for ddI (1.4 × 10^-6 cm/s, 98% recovery) and low Caco-2 uptake for lamivudine, neither affirmatively establishing F < 20%.",
      "card_ids": ["C60", "C70"]
    },
    {
      "claim": "The BCRP efflux and low-permeability records for GS-441524 and other non-AICAR molecules are mechanistic analog evidence with low transferability; no record shows that AICAR is a BCRP substrate or has intestinal first-pass loss sufficient to drive F below 20%.",
      "card_ids": ["C63", "C66", "C56", "C50", "C52"]
    },
    {
      "claim": "Low Caco-2 permeability for ribavirin is explicitly linked to limited hCNT2 expression in the assay, so in vitro permeability may under-predict transporter-mediated nucleoside absorption.",
      "card_ids": ["C52"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C59", "C60", "C61", "C62", "C63", "C64", "C65", "C66", "C67", "C68", "C69", "C70"]
    }
  ],
  "evidence_gaps": [
    "No AICAR-specific absolute oral bioavailability or systemic exposure measurement is supplied.",
    "No AICAR-specific intestinal permeability, gut-wall efflux, or intestinal metabolism data are supplied.",
    "L5 gut-wall records are for other molecules (aspalathin, GB0139, morroniside, GS-441524, lamivudine, ddI, gastrodin), not AICAR.",
    "No formulation, dose, prandial state, or species context for AICAR is supplied.",
    "Whether AICAR is a substrate of BCRP or other efflux transporters is uncharacterized.",
    "Caco-2/PAMPA low permeability may under-predict transporter-mediated nucleoside absorption, as noted for ribavirin and hCNT2."
  ],
  "decision_summary": "Prediction remains high: direct human nucleoside-analog F records support F ≥ 20%, and L5 gut-wall/efflux records are mostly non-AICAR mechanistic analog data that do not affirmatively establish F < 20%. Confidence remains low due to lack of AICAR-specific PK and low-permeability analog concerns."
}

